class Solution:
    def executeInstructions(self, n, startPos, s):
        m = len(s)
        delta = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
        res = []
        for i in range(m):
            r, c = startPos
            cnt = 0
            for ch in s[i:]:
                dr, dc = delta[ch]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    r, c = nr, nc
                    cnt += 1
                else:
                    break
            res.append(cnt)
        return res

