class Solution {
public:
    vector<int> executeInstructions(int n, vector<int>& startPos, string s) {
        int m = s.size();
        vector<int> res(m);
        int dr[128] = {0}, dc[128] = {0};
        dr['U'] = -1; dr['D'] = 1; dc['L'] = -1; dc['R'] = 1;
        for (int i = 0; i < m; i++) {
            int r = startPos[0], c = startPos[1], cnt = 0;
            for (int j = i; j < m; j++) {
                int nr = r + dr[(unsigned char)s[j]], nc = c + dc[(unsigned char)s[j]];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    r = nr; c = nc; cnt++;
                } else break;
            }
            res[i] = cnt;
        }
        return res;
    }
};

