class Solution {
    public int[] executeInstructions(int n, int[] startPos, String s) {
        int m = s.length();
        int[] res = new int[m];
        for (int i = 0; i < m; i++) {
            int r = startPos[0], c = startPos[1], cnt = 0;
            for (int j = i; j < m; j++) {
                int nr = r, nc = c;
                if (s.charAt(j) == 'U') nr--; else if (s.charAt(j) == 'D') nr++;
                else if (s.charAt(j) == 'L') nc--; else nc++;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    r = nr; c = nc; cnt++;
                } else break;
            }
            res[i] = cnt;
        }
        return res;
    }
}

